288		if err != nil {
289			return err
290		}
291		owner, repo, err := parseGitHubRepo(repoURL)
292		if err != nil {
293			return err
294		}
295		_, err = h.q.UpsertGitHubSource(ctx, database.UpsertGitHubSourceParams{
296			WorkspaceID:   uid,
297			RepoURL:       repoURL,
298			RepoOwner:     owner,
299			RepoName:      repo,
300			DefaultBranch: &defaultBranch,
301		})
302		if err != nil {
303			return fmt.Errorf("upsert github source: %w", err)
304		}
305		return nil
306	}
