308	func (h *serviceHandler) insertRunningRun(ctx context.Context, workspaceID, trigger, mode, branch string) (database.WorkspaceSyncRun, error) {
309		uid, err := pgUUID(workspaceID)
310		if err != nil {
311			return database.WorkspaceSyncRun{}, err
312		}
313		branchPtr := branch
314		row, err := h.q.InsertSyncRun(ctx, database.InsertSyncRunParams{
315			WorkspaceID:  uid,
316			Trigger:      trigger,
317			Branch:       &branchPtr,
318			Mode:         mode,
319			Status:       "running",
320			ChangedPaths: []byte("[]"),
321		})
322		if err != nil {
323			return database.WorkspaceSyncRun{}, fmt.Errorf("insert sync run: %w", err)
324		}
325		return row, nil
326	}
327	
328	func (h *serviceHandler) markRunFailed(ctx context.Context, runID pgtype.UUID, code, message string) error {
329		_, err := h.q.UpdateSyncRunFailed(ctx, database.UpdateSyncRunFailedParams{
330			ID:           runID,
331			ErrorCode:    &code,
332			ErrorMessage: &message,
333		})
334		if err != nil {
335			return fmt.Errorf("update sync run failed: %w", err)
336		}
337		return nil
338	}
339	
340	func uuidString(uid pgtype.UUID) string {
341		return uuid.UUID(uid.Bytes).String()
342	}
343	
344	func slugify(name string) string {
345		lower := strings.ToLower(name)
346		re := regexp.MustCompile(`[^a-z0-9]+`)
347		slug := re.ReplaceAllString(lower, "-")
348		return strings.Trim(slug, "-")
349	}
350	
351	func workspaceIDFromSyncPath(path string) (string, bool) {
352		const prefix = "/internal/workspaces/"
353		const suffix = "/sync"
354		if !strings.HasPrefix(path, prefix) || !strings.HasSuffix(path, suffix) {
355			return "", false
356		}
357		workspaceID := strings.TrimSuffix(strings.TrimPrefix(path, prefix), suffix)
358		workspaceID = strings.Trim(workspaceID, "/")
359		return workspaceID, workspaceID != ""
360	}
361	
362	func pgUUID(raw string) (pgtype.UUID, error) {
363		var uid pgtype.UUID
364		if err := uid.Scan(raw); err != nil {
365			return pgtype.UUID{}, domain.NewValidationError(domain.ErrValidationMissingInput, "invalid workspace_id: "+raw)
366		}
367		return uid, nil
368	}
369	
370	func parseGitHubRepo(raw string) (string, string, error) {
371		u, err := url.Parse(raw)
372		if err != nil || u.Host == "" {
373			return "", "", domain.NewValidationError(domain.ErrValidationInvalidURL, "invalid GitHub repo URL: "+raw)
374		}
375		if !strings.EqualFold(u.Host, "github.com") {
376			return "", "", domain.NewValidationError(domain.ErrValidationInvalidURL, "unsupported GitHub host: "+u.Host)
377		}
378		parts := strings.Split(strings.Trim(u.Path, "/"), "/")
379		if len(parts) < 2 || parts[0] == "" || parts[1] == "" {
380			return "", "", domain.NewValidationError(domain.ErrValidationInvalidURL, "invalid GitHub repo URL path: "+raw)
381		}
382		return parts[0], strings.TrimSuffix(parts[1], ".git"), nil
383	}
384	
385	func writeAnyError(w http.ResponseWriter, err error) {
386		var se domain.SourceError
387		if errors.As(err, &se) {
388			writeSourceError(w, se)
389			return
390		}
391		writeSourceError(w, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error()))
392	}
393	
394	func writeSourceError(w http.ResponseWriter, se domain.SourceError) {
395		status := http.StatusInternalServerError
396		switch se.Source {
397		case domain.ErrorSourceValidation:
398			status = http.StatusBadRequest
399		case domain.ErrorSourceGitHub:
400			switch se.Code {
401			case domain.ErrGitHubNotFound:
402				status = http.StatusNotFound
403			case domain.ErrGitHubUnauthorized:
404				status = http.StatusUnauthorized
405			case domain.ErrGitHubRateLimit:
406				status = http.StatusTooManyRequests
407			default:
408				status = http.StatusBadGateway
409			}
410		case domain.ErrorSourceDatabase:
411			if se.Code == domain.ErrDatabaseNotFound {
412				status = http.StatusNotFound
413			}
414		}
415		writeJSON(w, status, domain.FromSourceError(se, nil))
416	}
417	
418	func writeJSON(w http.ResponseWriter, status int, value interface{}) {
419		w.Header().Set("Content-Type", "application/json")
420		w.WriteHeader(status)
421		_ = json.NewEncoder(w).Encode(value)
422	}
