package main

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"log"
	"net/url"
	"regexp"
	"strings"
	"time"

	"github.com/google/uuid"
	"github.com/hibiken/asynq"
	"github.com/jackc/pgx/v5/pgtype"
	"github.com/jackc/pgx/v5/pgxpool"

	dbadapter "github.com/tiendv89/workspace-github-adapter/internal/adapter/db"
	"github.com/tiendv89/workspace-github-adapter/internal/config"
	"github.com/tiendv89/workspace-github-adapter/internal/database"
	"github.com/tiendv89/workspace-github-adapter/internal/domain"
	ghadapter "github.com/tiendv89/workspace-github-adapter/internal/github"
	"github.com/tiendv89/workspace-github-adapter/internal/queue"
)

func main() {
	cfg, err := config.Load()
	if err != nil {
		log.Fatalf("config: %v", err)
	}

	redisOpt, err := queue.RedisOpt(cfg.RedisURL)
	if err != nil {
		log.Fatalf("redis: %v", err)
	}

	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	pool, err := pgxpool.New(ctx, cfg.DatabaseURL)
	if err != nil {
		log.Fatalf("pgxpool.New: %v", err)
	}
	defer pool.Close()
	if err := pool.Ping(ctx); err != nil {
		log.Fatalf("ping db: %v", err)
	}

	h := &handler{
		db:     dbadapter.New(pool),
		q:      database.New(pool),
		github: ghadapter.New(cfg.GitHubToken),
		token:  cfg.GitHubToken,
	}

	srv := asynq.NewServer(redisOpt, asynq.Config{
		Concurrency: 5,
		Queues: map[string]int{
			"default": 1,
		},
	})

	mux := asynq.NewServeMux()
	mux.HandleFunc(queue.TypeWorkspaceSync, h.handleWorkspaceSync)

	log.Println("adapter-worker listening for Redis queue tasks")
	if err := srv.Run(mux); err != nil {
		log.Fatalf("worker stopped: %v", err)
	}
}

type handler struct {
	db     domain.DbWorkspaceAdapter
	q      *database.Queries
	github domain.GitHubWorkspaceAdapter
	token  string
}

func (h *handler) handleWorkspaceSync(ctx context.Context, t *asynq.Task) error {
	var payload queue.WorkspaceSyncPayload
	if err := json.Unmarshal(t.Payload(), &payload); err != nil {
		return fmt.Errorf("unmarshal payload: %w", err)
	}
	if payload.RepoURL == "" {
		return fmt.Errorf("repo_url is required")
	}
	if payload.WorkspaceID == "" {
		payload.WorkspaceID = uuid.NewString()
	}
	if payload.DefaultBranch == "" {
		payload.DefaultBranch = "main"
	}
	ref := payload.Ref
	if ref == "" {
		ref = payload.DefaultBranch
	}
	trigger := payload.Trigger
	if trigger == "" {
		trigger = "redis_worker"
	}
	mode := payload.Mode
	if mode == "" {
		mode = "full"
	}

	log.Printf("sync started workspace_id=%s repo_url=%s ref=%s", payload.WorkspaceID, payload.RepoURL, ref)

	snap, err := h.github.ImportWorkspace(ctx, domain.ImportInput{
		RepoURL:       payload.RepoURL,
		DefaultBranch: ref,
		Token:         h.token,
	})
	if err != nil {
		h.recordFailedRun(ctx, payload, trigger, mode, err)
		return err
	}
	snap.WorkspaceID = payload.WorkspaceID
	snap.RepoURL = payload.RepoURL
	if strings.TrimSpace(payload.Name) != "" {
		snap.Name = payload.Name
		snap.Slug = slugify(payload.Name)
	}

	if err := h.db.SaveSnapshot(ctx, payload.WorkspaceID, snap); err != nil {
		h.recordFailedRun(ctx, payload, trigger, mode, err)
		return err
	}
	if err := h.upsertGitHubSource(ctx, payload.WorkspaceID, payload.RepoURL, payload.DefaultBranch); err != nil {
		h.recordFailedRun(ctx, payload, trigger, mode, err)
		return err
	}
	if err := h.recordSuccessfulRun(ctx, payload, trigger, mode, ref, snap.CommitSHA); err != nil {
		return err
	}

	log.Printf("sync finished workspace_id=%s commit_sha=%s", payload.WorkspaceID, snap.CommitSHA)
	return nil
}

func (h *handler) upsertGitHubSource(ctx context.Context, workspaceID, repoURL, defaultBranch string) error {
	uid, err := pgUUID(workspaceID)
	if err != nil {
		return err
	}
	owner, repo, err := parseGitHubRepo(repoURL)
	if err != nil {
		return err
	}
	_, err = h.q.UpsertGitHubSource(ctx, database.UpsertGitHubSourceParams{
		WorkspaceID:   uid,
		RepoURL:       repoURL,
		RepoOwner:     owner,
		RepoName:      repo,
		DefaultBranch: &defaultBranch,
	})
	if err != nil {
		return fmt.Errorf("upsert github source: %w", err)
	}
	return nil
}

func (h *handler) recordSuccessfulRun(ctx context.Context, payload queue.WorkspaceSyncPayload, trigger, mode, branch, commitSHA string) error {
	commitPtr := commitSHA
	runID, err := h.ensureSyncRun(ctx, payload, trigger, mode, branch, &commitPtr)
	if err != nil {
		return err
	}
	_, err = h.q.UpdateSyncRunSuccess(ctx, database.UpdateSyncRunSuccessParams{
		ID:        runID,
		CommitSha: &commitPtr,
	})
	if err != nil {
		return fmt.Errorf("update sync run success: %w", err)
	}
	return nil
}

func (h *handler) recordFailedRun(ctx context.Context, payload queue.WorkspaceSyncPayload, trigger, mode string, syncErr error) {
	code := "WORKER_SYNC_FAILED"
	message := syncErr.Error()
	var sourceErr domain.SourceError
	if errors.As(syncErr, &sourceErr) {
		code = string(sourceErr.Code)
		message = sourceErr.Message
	}
	runID, err := h.ensureSyncRun(ctx, payload, trigger, mode, payload.DefaultBranch, nil)
	if err != nil {
		log.Printf("ensure failed sync run failed workspace_id=%s error=%v original_error=%v", payload.WorkspaceID, err, syncErr)
		return
	}
	if _, err := h.q.UpdateSyncRunFailed(ctx, database.UpdateSyncRunFailedParams{
		ID:           runID,
		ErrorCode:    &code,
		ErrorMessage: &message,
	}); err != nil {
		log.Printf("update failed sync run failed workspace_id=%s error=%v original_error=%v", payload.WorkspaceID, err, syncErr)
	}
}

func (h *handler) ensureSyncRun(ctx context.Context, payload queue.WorkspaceSyncPayload, trigger, mode, branch string, commitSHA *string) (pgtype.UUID, error) {
	if payload.SyncRunID != "" {
		return pgUUID(payload.SyncRunID)
	}
	uid, err := pgUUID(payload.WorkspaceID)
	if err != nil {
		return pgtype.UUID{}, err
	}
	branchPtr := branch
	row, err := h.q.InsertSyncRun(ctx, database.InsertSyncRunParams{
		WorkspaceID:  uid,
		Trigger:      trigger,
		Branch:       &branchPtr,
		Mode:         mode,
		Status:       "running",
		CommitSha:    commitSHA,
		ChangedPaths: []byte("[]"),
	})
	if err != nil {
		return pgtype.UUID{}, fmt.Errorf("insert sync run: %w", err)
	}
	return row.ID, nil
}

func slugify(name string) string {
	lower := strings.ToLower(name)
	re := regexp.MustCompile(`[^a-z0-9]+`)
	slug := re.ReplaceAllString(lower, "-")
	return strings.Trim(slug, "-")
}

func pgUUID(raw string) (pgtype.UUID, error) {
	var uid pgtype.UUID
	if err := uid.Scan(raw); err != nil {
		return pgtype.UUID{}, fmt.Errorf("invalid workspace_id %q: %w", raw, err)
	}
	return uid, nil
}

func parseGitHubRepo(raw string) (string, string, error) {
	u, err := url.Parse(raw)
	if err != nil || u.Host == "" {
		return "", "", fmt.Errorf("invalid GitHub repo URL: %s", raw)
	}
	if !strings.EqualFold(u.Host, "github.com") {
		return "", "", fmt.Errorf("unsupported GitHub host: %s", u.Host)
	}
	parts := strings.Split(strings.Trim(u.Path, "/"), "/")
	if len(parts) < 2 || parts[0] == "" || parts[1] == "" {
		return "", "", fmt.Errorf("invalid GitHub repo URL path: %s", raw)
	}
	return parts[0], strings.TrimSuffix(parts[1], ".git"), nil
}

package config

import (
	"fmt"
	"os"
	"strconv"
	"time"
)

// Config holds all runtime configuration for adapter-service.
type Config struct {
	// HTTP server
	Port int

	// Database
	DatabaseURL string

	// Redis / asynq task queue
	RedisURL string

	// GitHub
	GitHubToken string

	// Sync staleness threshold
	StaleThreshold time.Duration
}

// Load reads configuration from environment variables.
// Required variables: DATABASE_URL.
func Load() (*Config, error) {
	dbURL := os.Getenv("DATABASE_URL")
	if dbURL == "" {
		return nil, fmt.Errorf("DATABASE_URL is required")
	}

	port := 8080
	if raw := os.Getenv("PORT"); raw != "" {
		p, err := strconv.Atoi(raw)
		if err != nil {
			return nil, fmt.Errorf("invalid PORT: %w", err)
		}
		port = p
	}

	staleThreshold := 30 * time.Minute
	if raw := os.Getenv("STALE_THRESHOLD_MINUTES"); raw != "" {
		m, err := strconv.Atoi(raw)
		if err != nil {
			return nil, fmt.Errorf("invalid STALE_THRESHOLD_MINUTES: %w", err)
		}
		staleThreshold = time.Duration(m) * time.Minute
	}

	return &Config{
		Port:           port,
		DatabaseURL:    dbURL,
		RedisURL:       os.Getenv("REDIS_URL"),
		GitHubToken:    os.Getenv("GITHUB_TOKEN"),
		StaleThreshold: staleThreshold,
	}, nil
}

package domain

import "context"

// ImportInput is the input for the initial import of a workspace from GitHub.
type ImportInput struct {
	RepoURL       string
	DefaultBranch string
	Token         string // optional; falls back to GITHUB_TOKEN env var
}

// GitHubWorkspaceAdapter fetches and parses a GitHub management repository.
// It never reads from or writes to the database.
type GitHubWorkspaceAdapter interface {
	// ImportWorkspace performs a full reconciliation fetch of the given repository.
	// Returns a complete WorkspaceSnapshot or an error if the repo is inaccessible.
	ImportWorkspace(ctx context.Context, input ImportInput) (*WorkspaceSnapshot, error)

	// SyncWorkspace re-fetches the repository at the given ref (branch or SHA)
	// and returns an updated WorkspaceSnapshot.
	SyncWorkspace(ctx context.Context, workspaceID, repoURL, ref string) (*WorkspaceSnapshot, error)
}

// DbWorkspaceAdapter reads and writes workspace data in PostgreSQL.
// It never calls GitHub.
type DbWorkspaceAdapter interface {
	// ListWorkspaces returns summary rows for all saved workspaces.
	ListWorkspaces(ctx context.Context) ([]WorkspaceSummary, error)

	// GetWorkspace returns the full workspace detail for the given workspace ID.
	GetWorkspace(ctx context.Context, workspaceID string) (*WorkspaceDetail, error)

	// GetFeature returns the full feature detail for the given workspace and feature IDs.
	GetFeature(ctx context.Context, workspaceID, featureID string) (*FeatureDetail, error)

	// GetTask returns the full task detail for the given workspace, feature, and task IDs.
	GetTask(ctx context.Context, workspaceID, featureID, taskID string) (*TaskDetail, error)

	// ListFeatureTasks returns task summaries for all tasks in the given feature.
	ListFeatureTasks(ctx context.Context, workspaceID, featureID string) ([]TaskSummary, error)

	// ListActivity returns activity events filtered by the given scope.
	ListActivity(ctx context.Context, workspaceID string, scope ActivityScope) ([]ActivityEvent, error)

	// SaveSnapshot upserts all core tables from the given snapshot inside a single transaction.
	SaveSnapshot(ctx context.Context, workspaceID string, snapshot *WorkspaceSnapshot) error

	// GetActiveSnapshot returns the latest WorkspaceSnapshot for the given workspace.
	// Returns nil, nil when no snapshot has been saved yet.
	GetActiveSnapshot(ctx context.Context, workspaceID string) (*WorkspaceSnapshot, error)

	// GetLatestSyncRun returns the most recent sync run record for staleness derivation.
	// Returns nil, nil when no sync has been recorded.
	GetLatestSyncRun(ctx context.Context, workspaceID string) (*SyncRun, error)
}

package domain

import "time"

// SourceState describes the freshness and error state of a workspace's data.
type SourceState struct {
	Stale        bool       `json:"stale"`
	LastSyncedAt *time.Time `json:"last_synced_at,omitempty"`
	ErrorCode    string     `json:"error_code,omitempty"`
	ErrorMessage string     `json:"error_message,omitempty"`
}

// PullRequestRef is a reference to a pull request associated with a task.
type PullRequestRef struct {
	Label  string `json:"label"`
	URL    string `json:"url"`
	Status string `json:"status"`
	Repo   string `json:"repo"`
}

// ActivityEvent is a single normalized activity record from feature history or task logs.
type ActivityEvent struct {
	Action     string    `json:"action"`
	Scope      string    `json:"scope"`
	Actor      string    `json:"actor"`
	OccurredAt time.Time `json:"occurred_at"`
	Note       string    `json:"note,omitempty"`
	FeatureID  string    `json:"feature_id,omitempty"`
	TaskID     string    `json:"task_id,omitempty"`
}

// ActivityScope filters activity queries by scope.
type ActivityScope struct {
	FeatureID string
	TaskID    string
}

// WorkspaceSummary is the list-view representation of a workspace.
type WorkspaceSummary struct {
	ID          string      `json:"id"`
	Name        string      `json:"name"`
	Slug        string      `json:"slug"`
	RepoURL     string      `json:"repo_url"`
	SourceState SourceState `json:"source_state"`
	UpdatedAt   time.Time   `json:"updated_at"`
}

// WorkspaceDetail is the full workspace view including features and tasks.
type WorkspaceDetail struct {
	WorkspaceSummary
	Features []FeatureSummary `json:"features"`
	Tasks    []TaskSummary    `json:"tasks"`
}

// FeatureSummary is the list-view representation of a feature.
type FeatureSummary struct {
	ID           string     `json:"id"`
	FeatureID    string     `json:"feature_id"`
	Title        string     `json:"title"`
	Status       string     `json:"status"`
	CurrentStage string     `json:"current_stage,omitempty"`
	UpdatedAt    time.Time  `json:"updated_at"`
	TaskCounts   TaskCounts `json:"task_counts"`
}

// TaskCounts summarises task status distribution within a feature.
type TaskCounts struct {
	Total      int `json:"total"`
	Done       int `json:"done"`
	InProgress int `json:"in_progress"`
	Blocked    int `json:"blocked"`
	Ready      int `json:"ready"`
	Todo       int `json:"todo"`
}

// DocumentLink is a GitHub web URL for a feature document.
type DocumentLink struct {
	DocumentType string `json:"document_type"`
	SourcePath   string `json:"source_path"`
	URL          string `json:"url"`
}

// FeatureDetail is the full feature view including documents, tasks, and activity.
type FeatureDetail struct {
	FeatureSummary
	WorkspaceID string          `json:"workspace_id"`
	Documents   []DocumentLink  `json:"documents"`
	Tasks       []TaskSummary   `json:"tasks"`
	Activity    []ActivityEvent `json:"activity"`
	SourceState SourceState     `json:"source_state"`
}

// TaskSummary is the list-view representation of a task.
type TaskSummary struct {
	ID            string `json:"id"`
	TaskID        string `json:"task_id"`
	FeatureID     string `json:"feature_id"`
	FeatureName   string `json:"feature_name"`
	Title         string `json:"title"`
	Status        string `json:"status"`
	Repo          string `json:"repo,omitempty"`
	Branch        string `json:"branch,omitempty"`
	NextAction    string `json:"next_action,omitempty"`
	IsBlocked     bool   `json:"is_blocked"`
	BlockedReason string `json:"blocked_reason,omitempty"`
}

// ExecutionContext holds execution metadata for a task.
type ExecutionContext struct {
	ActorType     string `json:"actor_type"`
	LastUpdatedBy string `json:"last_updated_by,omitempty"`
	LastUpdatedAt string `json:"last_updated_at,omitempty"`
}

// TaskDetail is the full task view including dependencies, PR refs, and activity.
type TaskDetail struct {
	TaskSummary
	WorkspaceID    string           `json:"workspace_id"`
	DependsOn      []string         `json:"depends_on"`
	Execution      ExecutionContext `json:"execution"`
	PRRefs         []PullRequestRef `json:"pr_refs,omitempty"`
	BlockedContext *BlockedContext  `json:"blocked_context,omitempty"`
	Activity       []ActivityEvent  `json:"activity"`
}

// BlockedContext holds context about why a task is blocked and how to resume.
type BlockedContext struct {
	WIPBranch  string `json:"wip_branch,omitempty"`
	WIPSha     string `json:"wip_sha,omitempty"`
	PushedAt   string `json:"pushed_at,omitempty"`
	Suggestion string `json:"suggestion,omitempty"`
}

// WorkspaceSnapshot is the parsed in-memory representation of a GitHub workspace
// returned by GitHubWorkspaceAdapter. It is the input to the DB persistence layer.
type WorkspaceSnapshot struct {
	WorkspaceID      string
	Name             string
	Slug             string
	RepoURL          string
	ManagementRepoID string
	CommitSHA        string
	FetchedAt        time.Time
	Features         []FeatureSnapshot
	Repos            []RepoEntry
	SourceErrors     []SourceError
}

// RepoEntry maps to workspace.yaml repos[].
type RepoEntry struct {
	RepoID     string `json:"repo_id"`
	BaseBranch string `json:"base_branch,omitempty"`
}

// FeatureSnapshot is the parsed representation of a single feature directory.
type FeatureSnapshot struct {
	FeatureID    string
	Title        string
	Status       string
	CurrentStage string
	NextAction   string
	SourcePath   string
	SourceHash   string
	Documents    []DocumentSnapshot
	Tasks        []TaskSnapshot
	Activity     []ActivityEvent
}

// DocumentSnapshot is the parsed representation of a feature document.
type DocumentSnapshot struct {
	DocumentType string
	SourcePath   string
	URL          string
}

// TaskSnapshot is the parsed representation of a task YAML file.
type TaskSnapshot struct {
	TaskID        string
	FeatureID     string
	Title         string
	Status        string
	Repo          string
	Branch        string
	DependsOn     []string
	BlockedReason string
	Execution     map[string]interface{}
	PR            map[string]interface{}
	WorkspacePR   map[string]interface{}
	SourcePath    string
	SourceHash    string
	Activity      []ActivityEvent
}

