1	// Package github implements the GitHubWorkspaceAdapter interface.
2	// It uses the Git Trees API for feature discovery and the Contents API for
3	// individual file fetches — a single request discovers all feature paths,
4	// and only the relevant files are read. No archive download or zip extraction
5	// is required, and the same approach works for both full reconciliation and
6	// targeted sync.
7	package github
8	
9	import (
10		"context"
11		"fmt"
12		"net/url"
13		"os"
14		"strings"
15		"time"
16	
17		"github.com/tiendv89/workspace-github-adapter/internal/domain"
18	)
19	
20	// Adapter implements domain.GitHubWorkspaceAdapter.
21	type Adapter struct {
22		token string
23	}
24	
25	// New creates a new Adapter. If token is empty, the GITHUB_TOKEN environment
26	// variable is used as a fallback.
27	func New(token string) *Adapter {
28		if token == "" {
29			token = os.Getenv("GITHUB_TOKEN")
30		}
31		return &Adapter{token: token}
32	}
33	
34	// Ensure Adapter satisfies the interface at compile time.
35	var _ domain.GitHubWorkspaceAdapter = (*Adapter)(nil)
36	
37	// ImportWorkspace performs a full reconciliation import of the given repository.
38	func (a *Adapter) ImportWorkspace(ctx context.Context, input domain.ImportInput) (*domain.WorkspaceSnapshot, error) {
39		if err := validateInput(input); err != nil {
40			return nil, *err
41		}
42	
43		token := input.Token
44		if token == "" {
45			token = a.token
46		}
47		c := newClient(token)
48	
49		owner, repo, err := parseRepoURL(input.RepoURL)
50		if err != nil {
51			return nil, *err
52		}
53	
54		ref := input.DefaultBranch
55		if ref == "" {
56			ref = "main"
57		}
58	
59		return a.fetchSnapshot(ctx, c, owner, repo, ref, "")
60	}
61	
62	// SyncWorkspace re-fetches the repository at the given ref and returns an updated snapshot.
63	func (a *Adapter) SyncWorkspace(ctx context.Context, workspaceID, repoURL, ref string) (*domain.WorkspaceSnapshot, error) {
64		if repoURL == "" {
65			return nil, domain.NewValidationError(domain.ErrValidationMissingInput, "repoURL is required")
66		}
67		if ref == "" {
68			ref = "main"
69		}
70	
71		owner, repo, err := parseRepoURL(repoURL)
72		if err != nil {
73			return nil, *err
74		}
75	
76		c := newClient(a.token)
77		snap, fetchErr := a.fetchSnapshot(ctx, c, owner, repo, ref, workspaceID)
78		if fetchErr != nil {
79			return nil, fetchErr
80		}
81		return snap, nil
82	}
83	
84	// fetchSnapshot fetches the full workspace snapshot from GitHub.
85	func (a *Adapter) fetchSnapshot(ctx context.Context, c *client, owner, repo, ref, workspaceID string) (*domain.WorkspaceSnapshot, error) {
86		fetchedAt := time.Now().UTC()
87	
88		// Resolve the commit SHA for this ref.
89		commitSHA, err := c.getCommitSHA(ctx, owner, repo, ref)
90		if err != nil {
91			return nil, mapFetchError(err, owner, repo)
92		}
93	
94		// Fetch the full file tree in one request (Git Trees API, recursive=1).
95		// Pass commitSHA directly so getTree doesn't need to re-resolve the ref.
96		tree, err := c.getTree(ctx, owner, repo, commitSHA)
97		if err != nil {
98			return nil, mapFetchError(err, owner, repo)
99		}
100	
101		// Build a path-set for quick existence checks.
102		pathSet := make(map[string]struct{}, len(tree.Tree))
103		for _, e := range tree.Tree {
104			if e.Type == "blob" {
105				pathSet[e.Path] = struct{}{}
106			}
107		}
108	
109		// Fetch and parse workspace.yaml (required).
110		wsYAMLPath := "workspace.yaml"
111		wsData, err := c.getFileContent(ctx, owner, repo, wsYAMLPath, ref)
112		if err != nil {
113			return nil, mapFetchError(err, owner, repo)
114		}
115		if wsData == nil {
116			return nil, domain.SourceError{
117				Code:      domain.ErrGitHubNotFound,
118				Message:   fmt.Sprintf("required file not found: %s", wsYAMLPath),
119				Source:    domain.ErrorSourceGitHub,
120				Retryable: false,
121				Path:      wsYAMLPath,
122			}
123		}
124		wsCfg, parseErr := parseWorkspaceYAML(wsData, wsYAMLPath)
125		if parseErr != nil {
126			return nil, *parseErr
127		}
128	
129		// Discover feature directories from the tree.
130		featureIDs := discoverFeatureIDs(tree.Tree)
131	
132		// Map repos from workspace.yaml.
133		repos := make([]domain.RepoEntry, 0, len(wsCfg.Repos))
134		for _, r := range wsCfg.Repos {
135			repos = append(repos, domain.RepoEntry{
136				RepoID:     r.ID,
137				BaseBranch: r.BaseBranch,
138			})
139		}
140	
141		name := wsCfg.Name
142		if name == "" {
143			name = owner + "/" + repo
144		}
145		slug := slugify(name)
146		if workspaceID == "" {
147			workspaceID = slug
148		}
149	
150		var sourceErrors []domain.SourceError
151		features := make([]domain.FeatureSnapshot, 0, len(featureIDs))
152	
153		for _, featureID := range featureIDs {
154			feat, errs := a.fetchFeature(ctx, c, owner, repo, ref, featureID, pathSet)
155			sourceErrors = append(sourceErrors, errs...)
156			if feat != nil {
157				features = append(features, *feat)
158			}
159		}
160	
161		return &domain.WorkspaceSnapshot{
162			WorkspaceID:      workspaceID,
163			Name:             name,
164			Slug:             slug,
165			RepoURL:          "https://github.com/" + owner + "/" + repo,
166			ManagementRepoID: wsCfg.ManagementRepo,
167			CommitSHA:        commitSHA,
168			FetchedAt:        fetchedAt,
169			Features:         features,
170			Repos:            repos,
171			SourceErrors:     sourceErrors,
172		}, nil
173	}
174	
175	// fetchFeature fetches and parses all artifacts for a single feature.
176	func (a *Adapter) fetchFeature(ctx context.Context, c *client, owner, repo, ref, featureID string, pathSet map[string]struct{}) (*domain.FeatureSnapshot, []domain.SourceError) {
177		var errs []domain.SourceError
178	
179		docPaths := featureDocPaths(featureID)
180		statusPath := docPaths["status_yaml"]
181	
182		// status.yaml is required — if missing, emit a source error.
183		statusData, err := c.getFileContent(ctx, owner, repo, statusPath, ref)
184		if err != nil {
185			errs = append(errs, asSourceError(err, statusPath))
186			return nil, errs
187		}
188		if statusData == nil {
189			errs = append(errs, domain.SourceError{
190				Code:      domain.ErrGitHubNotFound,
191				Message:   fmt.Sprintf("required file not found: %s", statusPath),
192				Source:    domain.ErrorSourceGitHub,
193				Retryable: false,
194				Path:      statusPath,
195			})
196			return nil, errs
197		}
198	
199		status, parseErr := parseFeatureStatusYAML(statusData, statusPath)
200		if parseErr != nil {
201			errs = append(errs, *parseErr)
202			return nil, errs
203		}
204	
205		// Build document links — only status.yaml has required content; the rest are optional.
206		docs := []domain.DocumentSnapshot{}
207		for docType, docPath := range docPaths {
208			_, exists := pathSet[docPath]
209			if exists || docType == "status_yaml" {
210				docs = append(docs, domain.DocumentSnapshot{
211					DocumentType: docType,
212					SourcePath:   docPath,
213					URL:          buildWebURL(owner, repo, ref, docPath),
214				})
215			}
216		}
217	
218		// Fetch all task YAMLs for this feature.
219		tasksDir := "docs/features/" + featureID + "/tasks/"
220		var taskSnapshots []domain.TaskSnapshot
221		for p := range pathSet {
222			if !strings.HasPrefix(p, tasksDir) {
223				continue
224			}
225			taskID := taskFileBase(p)
226			if taskID == "" {
227				continue
228			}
229			taskData, err := c.getFileContent(ctx, owner, repo, p, ref)
230			if err != nil {
231				errs = append(errs, asSourceError(err, p))
232				continue
233			}
234			if taskData == nil {
235				continue
236			}
237			taskParsed, parseErr := parseTaskYAML(taskData, p)
238			if parseErr != nil {
239				errs = append(errs, *parseErr)
240				continue
241			}
242	
243			taskSnap := mapTaskSnapshot(taskParsed, featureID, taskID, p, taskData)
244			taskSnapshots = append(taskSnapshots, taskSnap)
245		}
246	
247		// Map feature history to activity events.
248		activity := mapActivityLog(status.History, "feature", featureID, "")
249	
250		return &domain.FeatureSnapshot{
251			FeatureID:    featureID,
252			Title:        status.Title,
253			Status:       status.Status,
254			CurrentStage: status.Stage,
255			NextAction:   status.NextAction,
256			SourcePath:   statusPath,
257			SourceHash:   hashContent(statusData),
258			Documents:    docs,
259			Tasks:        taskSnapshots,
260			Activity:     activity,
261		}, errs
262	}
263	
264	// mapTaskSnapshot converts a parsed taskYAML to a domain.TaskSnapshot.
265	func mapTaskSnapshot(t *taskYAML, featureID, taskID, sourcePath string, rawData []byte) domain.TaskSnapshot {
266		var activity []domain.ActivityEvent
267		if len(t.Log) > 0 {
268			activity = mapActivityLog(t.Log, "task", featureID, taskID)
269		}
270	
271		return domain.TaskSnapshot{
272			TaskID:        taskID,
273			FeatureID:     featureID,
274			Title:         t.Title,
275			Status:        t.Status,
276			Repo:          t.Repo,
277			Branch:        t.Branch,
278			DependsOn:     t.DependsOn,
279			BlockedReason: blockedReasonString(t.BlockedReason),
280			Execution:     t.Execution,
281			PR:            t.PR,
282			WorkspacePR:   t.WorkspacePR,
283			SourcePath:    sourcePath,
284			SourceHash:    hashContent(rawData),
285			Activity:      activity,
286		}
287	}
288	
289	// discoverFeatureIDs scans the tree entries for docs/features/*/status.yaml paths
290	// and returns the unique feature IDs found.
291	func discoverFeatureIDs(entries []treeEntry) []string {
292		seen := make(map[string]struct{})
293		var ids []string
294		for _, e := range entries {
295			if e.Type != "blob" {
296				continue
297			}
298			featureID, ok := extractFeatureID(e.Path)
299			if !ok {
300				continue
301			}
302			if _, dup := seen[featureID]; dup {
303				continue
304			}
305			seen[featureID] = struct{}{}
306			ids = append(ids, featureID)
307		}
308		return ids
309	}
310	
311	// validateInput checks ImportInput for required fields.
312	func validateInput(input domain.ImportInput) *domain.SourceError {
313		if input.RepoURL == "" {
314			se := domain.NewValidationError(domain.ErrValidationMissingInput, "RepoURL is required")
315			return &se
316		}
317		return nil
318	}
319	
320	// parseRepoURL extracts the owner and repo name from a GitHub URL.
321	// Accepts https://github.com/owner/repo and git@github.com:owner/repo.git forms.
322	func parseRepoURL(rawURL string) (owner, repo string, se *domain.SourceError) {
323		rawURL = strings.TrimSpace(rawURL)
324	
325		// SSH form: git@github.com:owner/repo.git
326		if strings.HasPrefix(rawURL, "git@github.com:") {
327			rest := strings.TrimPrefix(rawURL, "git@github.com:")
328			rest = strings.TrimSuffix(rest, ".git")
