1	package github
2	
3	import (
4		"context"
5		"encoding/base64"
6		"encoding/json"
7		"fmt"
8		"io"
9		"net/http"
10		"strconv"
11		"time"
12	
13		"github.com/tiendv89/workspace-github-adapter/internal/domain"
14	)
15	
16	const (
17		apiBase        = "https://api.github.com"
18		defaultTimeout = 30 * time.Second
19	)
20	
21	// client is an authenticated GitHub API client.
22	type client struct {
23		http  *http.Client
24		token string
25	}
26	
27	func newClient(token string) *client {
28		return &client{
29			http:  &http.Client{Timeout: defaultTimeout},
30			token: token,
31		}
32	}
33	
34	// do executes an HTTP request and returns the response body bytes.
35	// It handles GitHub error responses and maps them to domain.SourceError.
36	func (c *client) do(ctx context.Context, url string) ([]byte, error) {
37		req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
38		if err != nil {
39			return nil, domain.SourceError{
40				Code:      domain.ErrAdapterInternal,
41				Message:   fmt.Sprintf("failed to build request: %v", err),
42				Source:    domain.ErrorSourceAdapter,
43				Retryable: false,
44			}
45		}
46		req.Header.Set("Accept", "application/vnd.github+json")
47		req.Header.Set("X-GitHub-Api-Version", "2022-11-28")
48		if c.token != "" {
49			req.Header.Set("Authorization", "Bearer "+c.token)
50		}
51	
52		resp, err := c.http.Do(req)
53		if err != nil {
54			if ctx.Err() != nil {
55				return nil, domain.SourceError{
56					Code:      domain.ErrAdapterTimeout,
57					Message:   "request cancelled or timed out",
58					Source:    domain.ErrorSourceAdapter,
59					Retryable: true,
60				}
61			}
62			return nil, domain.NewGitHubNetworkError(err.Error())
63		}
64		defer resp.Body.Close()
65	
66		body, err := io.ReadAll(resp.Body)
67		if err != nil {
68			return nil, domain.NewGitHubNetworkError("failed to read response body: " + err.Error())
69		}
70	
71		switch resp.StatusCode {
72		case http.StatusOK:
73			return body, nil
74		case http.StatusUnauthorized, http.StatusForbidden:
75			if resp.StatusCode == http.StatusForbidden && resp.Header.Get("X-RateLimit-Remaining") == "0" {
76				resetAt := resp.Header.Get("X-RateLimit-Reset")
77				msg := ""
78				if resetAt != "" {
79					if ts, err := strconv.ParseInt(resetAt, 10, 64); err == nil {
80						msg = fmt.Sprintf("Try again after %s.", time.Unix(ts, 0).UTC().Format(time.RFC3339))
81					}
82				}
83				return nil, domain.NewGitHubRateLimitError(msg)
84			}
85			return nil, domain.SourceError{
86				Code:      domain.ErrGitHubUnauthorized,
87				Message:   "GitHub API request unauthorized — check GITHUB_TOKEN",
88				Source:    domain.ErrorSourceGitHub,
89				Retryable: false,
90			}
91		case http.StatusNotFound:
92			return nil, domain.SourceError{
93				Code:      domain.ErrGitHubNotFound,
94				Message:   fmt.Sprintf("GitHub resource not found: %s", url),
95				Source:    domain.ErrorSourceGitHub,
96				Retryable: false,
97			}
98		case http.StatusTooManyRequests:
99			retryAfter := resp.Header.Get("Retry-After")
100			return nil, domain.NewGitHubRateLimitError("Retry-After: " + retryAfter)
101		default:
102			if resp.StatusCode >= 500 {
103				return nil, domain.SourceError{
104					Code:      domain.ErrGitHubServerError,
105					Message:   fmt.Sprintf("GitHub API server error (HTTP %d)", resp.StatusCode),
106					Source:    domain.ErrorSourceGitHub,
107					Retryable: true,
108				}
109			}
110			return nil, domain.SourceError{
111				Code:      domain.ErrGitHubNetworkError,
112				Message:   fmt.Sprintf("GitHub API unexpected response (HTTP %d)", resp.StatusCode),
113				Source:    domain.ErrorSourceGitHub,
114				Retryable: false,
115			}
116		}
117	}
118	
119	// treeEntry is a single entry returned by the Git Trees API.
120	type treeEntry struct {
121		Path string `json:"path"`
122		Type string `json:"type"` // "blob" or "tree"
123		SHA  string `json:"sha"`
124		Size int    `json:"size,omitempty"`
125	}
126	
127	// gitTreeResponse is the response from the Git Trees API.
128	type gitTreeResponse struct {
129		SHA       string      `json:"sha"`
130		Tree      []treeEntry `json:"tree"`
131		Truncated bool        `json:"truncated"`
132	}
133	
134	// contentResponse is the response from the Contents API.
135	type contentResponse struct {
136		Encoding string `json:"encoding"`
137		Content  string `json:"content"`
138		SHA      string `json:"sha"`
139	}
140	
141	// commitResponse is used to extract commit SHA from a branch/ref query.
142	type commitResponse struct {
143		Commit struct {
144			SHA string `json:"sha"`
145		} `json:"commit"`
146		SHA string `json:"sha"` // for tag and commit refs
147	}
148	
149	// getTree fetches the full recursive file tree for a repo using the given commit SHA.
150	// The caller is responsible for resolving the ref to a SHA via getCommitSHA before calling this.
151	func (c *client) getTree(ctx context.Context, owner, repo, sha string) (*gitTreeResponse, error) {
152		url := fmt.Sprintf("%s/repos/%s/%s/git/trees/%s?recursive=1", apiBase, owner, repo, sha)
153		body, err := c.do(ctx, url)
154		if err != nil {
155			return nil, err
156		}
157	
158		var tree gitTreeResponse
159		if err := json.Unmarshal(body, &tree); err != nil {
